function testCsvLine() {
  console.log(csvLine(["Tomato", "Bed 3, south", 'The "big" one']))
}

function csvLine(values) {
  let line = ""
  for (let i = 0; i < values.length; i++) {
    if (i > 0) {
      line += ","
    }
    const escaped = values[i].replaceAll('"', '""')
    line += '"' + escaped + '"'
  }
  return line
}
